# Try: swap colors AND make each half internally symmetric
def swap_colors_and_internal_symmetry(grid):
    result = [[0]*9 for _ in range(len(grid))]

    for r in range(len(grid)):
        # Left half with color 2 (swapped) and internal symmetry
        left_vals = [grid[r][c] for c in range(4)]
        for c in range(4):
            if left_vals[c] == 1:
                left_vals[c] = 2

            val_left = left_vals[c]
            val_mirror = left_vals[3-c]

            if val_left != 0 and val_mirror == 0:
                val_use = val_left
            elif val_left == 0 and val_mirror != 0:
                val_use = val_mirror
            else:
                val_use = max(val_left, val_mirror) if val_left > 0 or val_mirror > 0 else 0

            result[r][c] = val_use
            result[r][3-c] = val_use

        # Right half with color 1 (swapped) and internal symmetry
        right_vals = [grid[r][5+c] for c in range(4)]
        for c in range(4):
            if right_vals[c] == 2:
                right_vals[c] = 1

            val_right = right_vals[c]
            val_mirror = right_vals[3-c]

            if val_right != 0 and val_mirror == 0:
                val_use = val_right
            elif val_right == 0 and val_mirror != 0:
                val_use = val_mirror
            else:
                val_use = max(val_right, val_mirror) if val_right > 0 or val_mirror > 0 else 0

            result[r][5+c] = val_use
            result[r][8-c] = val_use

    return result

